// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, bytes calldata data) public {
        vm.assume(amount > 0 && amount <= 1_000_000 ether);
        address owner = c.Owner();
        vm.deal(owner, amount);
        ETHCollector collector = new ETHCollector();
        uint256 balBefore = address(collector).balance;
        vm.prank(owner);
        c.Command{value: amount}(address(collector), data);
        assertTrue(address(collector).balance == balBefore + amount);
    }
}

contract ETHCollector {
    fallback() external payable {}
    receive() external payable {}
}
